# Cross-arch binary - addr2line works but objdump may not. Let's try readelf + nm approach
# Get all FUNC symbols sorted, then find the enclosing function for our addresses
nm --defined-only /tmp/libmonosgen-2.0.so.dbg 2>/dev/null | grep -i ' [tT] ' | sort | awk '
{
  addr = strtonum("0x" $1)
  name = $3
  addrs[NR] = addr
  names[NR] = name
  count = NR
}
END {
  targets[1] = strtonum("0x2f4b20")
  targets[2] = strtonum("0x2f4c84")
  for (t = 1; t <= 2; t++) {
    best = ""
    bestaddr = 0
    for (i = 1; i <= count; i++) {
      if (addrs[i] <= targets[t] && addrs[i] > bestaddr) {
        bestaddr = addrs[i]
        best = names[i]
      }
    }
    printf "0x%x => %s (at 0x%x, offset +0x%x)\n", targets[t], best, bestaddr, targets[t] - bestaddr
  }
}'

