  name = $3
  addrs[NR] = addr
  names[NR] = name
  count = NR
}
END {
  targets[1] = strtonum("0x2f4b20")
  targets[2] = strtonum("0x2f4c84")
  labels[1] = "0x2f4b20"
  labels[2] = "0x2f4c84"
  for (t = 1; t <= 2; t++) {
    best = ""
    bestaddr = 0
    nextname = ""
    nextaddr = 0
    for (i = 1; i <= count; i++) {
      if (addrs[i] <= targets[t] && addrs[i] > bestaddr) {
        bestaddr = addrs[i]
        best = names[i]
